"""The runner firmware (generated by firmware/patches/patch_pmu_events_source.py) and host/lib/pmwl.py declare the
PMWL layout independently. This test reads the generated C and requires every header word, knob word, TA table
and limit to agree with pmwl.py. A change on one side only must turn this RED."""
import re, sys, unittest, pathlib
REPO = pathlib.Path(__file__).resolve().parents[2]
sys.path.insert(0, str(REPO / "host" / "lib")); sys.path.insert(0, str(REPO / "firmware" / "patches"))
import pmwl
import pmu_events_parse
import patch_pmu_events_source as P

GEN = P.generate((REPO / "firmware" / "Selftest_pmu" / "runner_pmu_main.c").read_text())
BLK = GEN[GEN.index("#if defined(PMU_EVENTS_MODEL)"):GEN.index("#endif /* PMU_EVENTS_MODEL */")]
W = pmwl.word


def c_ints(text):
    return [int(x, 0) for x in re.findall(r"0x[0-9A-Fa-f]+|\d+", text.replace("U", ""))]


def c_array(name):
    m = re.search(re.escape(name) + r"[^=]*=\s*(\{.*?\});", BLK, re.S)
    if not m:
        raise AssertionError(f"{name} not found in the generated runner")
    body = re.sub(r"/\*.*?\*/", "", m.group(1), flags=re.S)
    return c_ints(body)


class Header(unittest.TestCase):
    def test_magic_and_off(self):
        self.assertIn(f"#define PMWL_MAGIC 0x{pmwl.MAGIC:08X}U", GEN)
        self.assertIn(f"#define PMWL_OFF 0x{pmwl.OFF:08X}U", GEN)

    def test_header_words_used_by_the_runner(self):
        for stmt in (f"h[{W('total_len')}] != model_total_length",
                     f"memcpy(cmd, s + h[{W('cms_off')}], h[{W('cms_len')}]);",
                     f"memcpy(cst, s + h[{W('const_off')}], h[{W('const_len')}]);",
                     f"arena = dram; dram += pmwl_al256(h[{W('arena_size')}]);",
                     f"h[{W('fast_size')}] > PMWL_SRAM_END - h[{W('fast_base')}]",
                     f"x.out_ver_data_0 = s + h[{W('golden_off')}];",
                     f"__real_test_u85(eTest, h[{W('irq_mask')}], h[{W('ofm_len')}], h[{W('cms_len')}], &x);"):
            self.assertIn(stmt, BLK, stmt)

    def test_versions_and_knob_span(self):
        self.assertIn(f"h[{W('version')}] < 1U || h[{W('version')}] > 4U", BLK)
        self.assertIn(f"memcpy(&h[{pmwl.HEADER_WORDS}], s + {4 * pmwl.HEADER_WORDS}U, "
                      f"((h[1] >= 3U) ? {pmwl.KNOB_WORDS}U : 8U) * 4U);", BLK)
        self.assertIn(f"if (h[1] == 2U) {{ h[{pmwl.HEADER_WORDS + pmwl.V2_KNOBS}] = PMWL_OFF; }}", BLK)


class IoTable(unittest.TestCase):
    """Version 4: the runner reads the IO table where pmwl.py writes it and walks every entry."""

    def test_table_place_and_size(self):
        self.assertIn(f"#define PMWL_IO_MAX {pmwl.IO_MAX}U", BLK)
        self.assertIn("uint32_t io[2U + 3U * PMWL_IO_MAX]", BLK)
        self.assertEqual(pmwl.IO_WORDS, 2 + 3 * pmwl.IO_MAX)
        self.assertIn("if (h[1] == 4U) {", BLK)
        self.assertIn(f"memcpy(io, s + {4 * pmwl.IO_WORD}U, sizeof io);", BLK)

    def test_entry_layout_is_the_header_ifm_ofm_words(self):
        # an entry is (arena_off, len, data_off); entry 0 of each list repeats header words 8..10 / 11..13
        self.assertEqual(pmwl.HEADER_FIELDS[W("ifm_arena_off"):W("golden_off") + 1],
                         ("ifm_arena_off", "ifm_len", "ifm_data_off", "ofm_arena_off", "ofm_len", "golden_off"))
        self.assertIn(f"io[2] != h[{W('ifm_arena_off')}] || io[3] != h[{W('ifm_len')}] "
                      f"|| io[4] != h[{W('ifm_data_off')}]", BLK)
        self.assertIn(f"io[2U + 3U * io[0]] != h[{W('ofm_arena_off')}] || io[3U + 3U * io[0]] != h[{W('ofm_len')}] "
                      f"|| io[4U + 3U * io[0]] != h[{W('golden_off')}]", BLK)
        self.assertIn(f"for (i = 0U; i < 6U; i++) {{ io[2U + i] = h[{W('ifm_arena_off')}U + i]; }}", BLK)
        self.assertIn("io[0] = 1U; io[1] = 1U;", BLK)

    def test_counts_and_bounds_refused(self):
        self.assertIn("io[0] < 1U || io[1] < 1U || io[1] > PMWL_IO_MAX || io[0] > PMWL_IO_MAX - io[1]", BLK)
        self.assertIn(f"io[e + 1U] > h[{W('arena_size')}] || io[e] > h[{W('arena_size')}] - io[e + 1U] "
                      f"|| io[e + 1U] > h[{W('total_len')}] || io[e + 2U] > h[{W('total_len')}] - io[e + 1U]", BLK)
        self.assertIn("for (k = 0U; k < io[0] + io[1]; k++) {\n        e = 2U + 3U * k;\n        if (", BLK)

    def test_every_ifm_copied_every_ofm_poisoned_and_compared(self):
        poison = ("for (k = 0U; k < io[1]; k++) {  /* poison every OFM, then copy every IFM (they may overlap) */\n"
                  "        e = 2U + 3U * (io[0] + k);\n        memset(arena + io[e], 0xA5, io[e + 1U]);\n    }\n")
        copy = ("for (k = 0U; k < io[0]; k++) {\n        e = 2U + 3U * k;\n"
                "        memcpy(arena + io[e], s + io[e + 2U], io[e + 1U]);\n    }\n")
        self.assertIn(poison + "    " + copy, BLK)            # poison before copy: an IFM may share an OFM's bytes
        compare = BLK[BLK.index("at = 0U;"):BLK.index("if (pmwl_knob_pending) { pmwl_knob_bad = 1U; }")]
        for stmt in ("for (k = 0U; k < io[1]; k++) {", "e = 2U + 3U * (io[0] + k);",
                     "o = (const int8_t *)(arena + io[e]);", "g = (const int8_t *)(s + io[e + 2U]);",
                     "for (i = 0U; i < io[e + 1U]; i++, at++) {", "if (ofm_mm_count == 0U) { ofm_mm_first = at; }",
                     "ofm_mm_count++;"):
            self.assertIn(stmt, compare, stmt)
        self.assertLess(BLK.index(copy), BLK.index("rc = __real_test_u85("))
        self.assertLess(BLK.index("rc = __real_test_u85("), BLK.index("at = 0U;"))


class Knobs(unittest.TestCase):
    def test_register_knobs_in_order(self):
        # the runner copies words 17..24 into pmwl_knob[] and applies them to these registers, in this order
        self.assertIn(f"pmwl_knob[i] = h[{W('regioncfg')}U + i];", BLK)
        off = GEN[GEN.index("static const uint32_t off[8] = {"):]
        off = off[:off.index("};")]
        order = re.findall(r"NPU_OFF_(\w+)(?: \+ (\d+)U)?", off)
        names = [("mem_attr%d" % (int(d or 0) // 4)) if r == "MEM_ATTR0" else r.lower() for r, d in order]
        self.assertEqual(names, list(pmwl.KNOB_FIELDS[W("regioncfg") - 16:W("axi_ext") - 16 + 1]))
        self.assertEqual(W("axi_ext") - W("regioncfg") + 1, 8)

    def test_scalar_knobs(self):
        self.assertIn(f"pmu_reg_write(NPU_REG_PMCAXI_CHAN_ABS, h[{W('axi_chan')}]);", BLK)
        self.assertIn(f"pmwl_power_ctrl = h[{W('power_ctrl')}];", BLK)
        self.assertIn(f"fast = (uint8_t *)(uintptr_t)h[{W('fast_base')}];", BLK)
        self.assertIn(f"if (h[{W('ta_profile')}] != PMWL_OFF) {{", BLK)
        self.assertIn(f"if (h[{W('ta_profile')}] < 1U || h[{W('ta_profile')}] > {max(pmwl.TA_PROFILES)}U)", BLK)
        self.assertIn(f"if (pmwl_ta_apply(h[{W('ta_profile')}]) != 0U)", BLK)
        self.assertIn(f"if (h[{W('fast_base')}] != PMWL_OFF) {{", BLK)
        self.assertIn(f"if (h[{W('axi_chan')}] != PMWL_OFF) {{", BLK)
        self.assertEqual(sorted(pmwl.TA_PROFILES), list(range(1, max(pmwl.TA_PROFILES) + 1)))

    def test_knob_not_honoured_rc(self):
        # the host validity term knobs_honoured matches the rc the runner returns on a read-back failure
        self.assertIn(f"#define PMWL_KNOB_NOT_HONOURED 0x{pmu_events_parse.KNOB_NOT_HONOURED:X}\n", GEN)

    def test_onchip_sram_end(self):
        self.assertIn(f"#define PMWL_SRAM_END 0x{pmwl.ONCHIP_SRAM[1]:08X}U", BLK)


class TimingAdapter(unittest.TestCase):
    def test_bases_version_offsets(self):
        self.assertEqual(c_array("pmwl_ta_base[2]"), [pmwl.TA_BASE["sram"], pmwl.TA_BASE["ext"]])
        self.assertIn(f"#define PMWL_TA_VERSION 0x{pmwl.TA_VERSION:04X}U", BLK)
        self.assertEqual(c_array("pmwl_ta_off[11]"), [off for _, off in pmwl.TA_REGS])

    def test_profile_values(self):
        want = [pmwl.TA_PROFILES[p][port][reg] for p in sorted(pmwl.TA_PROFILES)
                for port in ("sram", "ext") for reg, _ in pmwl.TA_REGS]
        self.assertEqual(c_array("pmwl_ta_val[2][2][11]"), want)


if __name__ == "__main__":
    unittest.main()
